// #1a311effdd4a2d2ba5fe9c67 — сбой сети при старте практики показывает кандидату объяснение, «נסו שוב» и путь к человеку;
// после восстановления сети повтор стартует практику ровно один раз, на подключении — подсказка открыть приветствием.
// Кейсы CALL-001, CALL-002. НЕ prod-safe: создаёт кандидата «QA-AUTO-CALL-P-…» (link_only), тратит практику и AI-голос
// (официальная попытка не тратится). Кандидат не удаляется (правило проекта — только с «да»).
// Сбой — настоящий: context.setOffline(true), ответы не подменяются.
import { test, expect } from '../../fixtures';
import { runStamp } from '../support/api';
import {
  Candidate, TXT, createCandidateLink, launchCandidate, goToPractice, tap,
  expectStartFailure, expectHelpPath, waitConnectingHint, scrollWidth,
} from './support';

test.describe.configure({ mode: 'serial' });

let cand: Candidate | undefined;

test.afterAll(async () => {
  await cand?.browser.close();
});

test.describe('Звонок кандидата — сбой старта практики (#1a311effdd4a2d2ba5fe9c67) @call', () => {
  test('offline → «להתחיל תרגול»: объяснение «כנראה בגלל תקלה בחיבור לאינטרנט», «נסו שוב», «לפנות לצוות לעזרה»; шаг не перезагружается @desktop @data #1a311effdd4a2d2ba5fe9c67', async ({ asUser }) => {
    test.setTimeout(5 * 60_000);
    const business = await asUser('business');
    const name = `QA-AUTO-CALL-P-${runStamp()}`;
    const link = await createCandidateLink(business, name);
    test.info().annotations.push({ type: 'test-data', description: `кандидат «${name}» (практика использована), не удаляется` });

    cand = await launchCandidate({ width: 390, height: 844 });
    const { page, ctx, counts } = cand;
    await goToPractice(page, link);
    const url = page.url();

    // Источник: AC — «כשל רשת בבקשת התחלת התרגול … מציג למועמד הסבר, ניסיון חוזר ונתיב פנייה».
    await ctx.setOffline(true);
    await tap(page, 'להתחיל תרגול');
    await expectStartFailure(page, TXT.practiceFail);
    expect(page.url(), 'шаг перезагрузился').toBe(url);
    await expect(page.getByText('פרטי לקוח לתרגול')).toBeVisible();
    expect(counts.start, 'запросов candidate_start_attempt на одно нажатие').toBe(1);
    const w = await scrollWidth(page);
    expect(w.sw, 'горизонтальная прокрутка').toBeLessThanOrEqual(w.vw);

    await expectHelpPath(page, TXT.practiceFail);

    await tap(page, TXT.retry);
    await expect.poll(() => counts.start).toBe(2);
    await expectStartFailure(page, TXT.practiceFail);
    expect(counts.voice, 'start-voice-session без сети').toBe(0);
  });

  test('сеть восстановлена → «נסו שוב»: практика стартует ровно 1 раз, на подключении подсказка «פתחו בברכה» @desktop @data #1a311effdd4a2d2ba5fe9c67', async () => {
    test.setTimeout(2 * 60_000);
    expect(cand, 'нет состояния из предыдущего теста').toBeTruthy();
    const { page, ctx, counts } = cand!;
    const before = counts.start;

    await ctx.setOffline(false);
    const hint = waitConnectingHint(page);
    await tap(page, TXT.retry);

    // Источник: «מה רצוי» — «מסך ההתחברות מציג את ההנחיה לפתוח בברכה».
    expect(await hint).toBe(TXT.hint);
    await expect(page.getByText('מצב תרגול')).toBeVisible({ timeout: 30_000 });
    await expect(page.getByRole('button', { name: 'לסיים שיחה' })).toBeVisible();
    await expect(page.getByText(TXT.practiceFail)).toBeHidden();
    // Источник: AC — «ניסיון חוזר»: повтор стартует один раз.
    expect(counts.start - before, 'candidate_start_attempt после повтора').toBe(1);
    expect(counts.voice, 'start-voice-session после повтора').toBe(1);
  });
});
